CompositionLocalProvider(LocalConfiguration provides locale) {
    @OptIn(ExperimentalMonarchApi::class)
    MonarchGanttTimeline(
        items = items,
        previousIcon = { Icon(SampleIcons.ChevronLeft, contentDescription = null) },
        nextIcon = { Icon(SampleIcons.ChevronRight, contentDescription = null) },
        state = state,
        dependencies = listOf(
            MonarchGanttTimelineDependency({{dependencies.0.id}}, {{dependencies.0.from}}, {{dependencies.0.to}}),
            MonarchGanttTimelineDependency({{dependencies.1.id}}, {{dependencies.1.from}}, {{dependencies.1.to}}, conflict = {{dependencies.1.conflict}}),
            MonarchGanttTimelineDependency({{dependencies.2.id}}, {{dependencies.2.from}}, {{dependencies.2.to}}, kind = MonarchGanttTimelineDependencyKind.{{dependencies.2.kind|pascal}}),
        ),
        milestones = listOf(
            MonarchGanttTimelineMilestone({{milestones.0.id}}, {{milestones.0.label}}, {{milestones.0.date|millis}}),
            MonarchGanttTimelineMilestone({{milestones.1.id}}, {{milestones.1.label}}, {{milestones.1.date|millis}}),
        ),
        today = {{today|millis}},
        timeZone = "UTC",
        labels = MonarchGanttTimelineLabels(list = "Table"),
        onChange = { item, dates ->
            items = items.map {
                if (it.id != item.id) it else MonarchGanttTimelineItem(
                    it.id,
                    it.label,
                    dates.start,
                    dates.end,
                    parentId = it.parentId,
                    progress = it.progress,
                    tone = it.tone,
                    conflict = it.conflict,
                    meta = it.meta,
                )
            }
            // The app saves item.id with dates.start and dates.end here.
        },
        onOpen = { /* The app opens it.id here. */ },
    )
}

