var items by remember {
    mutableStateOf(
        listOf(
            MonarchGanttTimelineItem({{tasks.0.id}}, {{tasks.0.label}}, start = {{tasks.0.start|millis}}, end = {{tasks.0.end|millis}}, progress = {{tasks.0.progress}} / 100f, tone = {{tasks.0.tone|tone}}),
            MonarchGanttTimelineItem({{tasks.1.id}}, {{tasks.1.label}}, start = {{tasks.1.start|millis}}, end = {{tasks.1.end|millis}}, progress = {{tasks.1.progress}} / 100f),
            MonarchGanttTimelineItem({{tasks.2.id}}, {{tasks.2.label}}, start = {{tasks.2.start|millis}}, end = {{tasks.2.end|millis}}, conflict = {{tasks.2.conflict}}),
            MonarchGanttTimelineItem({{tasks.3.id}}, {{tasks.3.label}}, start = {{tasks.3.start|millis}}, end = {{tasks.3.end|millis}}, parentId = {{tasks.3.parentId}}),
            MonarchGanttTimelineItem({{tasks.4.id}}, {{tasks.4.label}}, start = {{tasks.4.start|millis}}, end = {{tasks.4.end|millis}}, parentId = {{tasks.4.parentId}}),
            MonarchGanttTimelineItem({{tasks.5.id}}, {{tasks.5.label}}, end = {{tasks.5.end|millis}}, meta = {{tasks.5.meta}}),
            MonarchGanttTimelineItem({{tasks.6.id}}, {{tasks.6.label}}),
        ),
    )
}
val state = rememberMonarchGanttTimelineState(initialStart = {{defaultStart|millis}})
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}

